&Options = new() &OptionsDesc = new() &OptionIndexes = new() LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_REMPERIODO1' Do 'LoadremPeriodo1Options' Case &DDOName.ToUpper() = !'DDO_REMPERIODO2' Do 'LoadremPeriodo2Options' Case &DDOName.ToUpper() = !'DDO_REMPERIODO3' Do 'LoadremPeriodo3Options' Case &DDOName.ToUpper() = !'DDO_REMPERIODO4' Do 'LoadremPeriodo4Options' Case &DDOName.ToUpper() = !'DDO_REMPERIODO5' Do 'LoadremPeriodo5Options' EndCase
&OptionsJson = &Options.ToJson() &OptionsDescJson = &OptionsDesc.ToJson() &OptionIndexesJson = &OptionIndexes.ToJson()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessasWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMCODIGO" &TFremCodigo.FromString(&GridStateFilterValue.Value) &TFremCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMCADASTRO" &TFremCadastro.FromString(&GridStateFilterValue.Value) &TFremCadastro_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPERIODO1" &TFremPeriodo1.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO1_SEL" &TFremPeriodo1_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2" &TFremPeriodo2.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2_SEL" &TFremPeriodo2_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3" &TFremPeriodo3.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3_SEL" &TFremPeriodo3_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4" &TFremPeriodo4.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4_SEL" &TFremPeriodo4_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5" &TFremPeriodo5.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5_SEL" &TFremPeriodo5_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMSTATUS_SEL" &TFremStatus_SelsJson = &GridStateFilterValue.Value &TFremStatus_Sels.FromJson(&TFremStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'REMCADASTRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCadastro1.FromString(&GridStateDynamicFilter.Value) &remCadastro_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'REMSTATUS' &remStatus1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'REMCADASTRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCadastro2.FromString(&GridStateDynamicFilter.Value) &remCadastro_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'REMSTATUS' &remStatus2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'REMCADASTRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCadastro3.FromString(&GridStateDynamicFilter.Value) &remCadastro_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'REMSTATUS' &remStatus3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadremPeriodo1Options'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFremPeriodo1 = &SearchTxt &TFremPeriodo1_Sel.SetEmpty() For Each trnsremessas using trnsremessasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &remCodigo1, &remCadastro1, &remCadastro_To1, &remStatus1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &remCodigo2, &remCadastro2, &remCadastro_To2 , &remStatus2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &remCodigo3, &remCadastro3 , &remCadastro_To3, &remStatus3, &TFremCodigo, &TFremCodigo_To, &TFremCadastro, &TFremCadastro_To , &TFremPeriodo1, &TFremPeriodo1_Sel, &TFremPeriodo2, &TFremPeriodo2_Sel, &TFremPeriodo3, &TFremPeriodo3_Sel , &TFremPeriodo4, &TFremPeriodo4_Sel, &TFremPeriodo5, &TFremPeriodo5_Sel, &TFremStatus_Sels) Where prefCodigo = &prefCodigo
If not remPeriodo1.IsEmpty() &Option = remPeriodo1
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &Options.Item(&InsertIndex) < &Option &InsertIndex = &InsertIndex + 1 EndDo If &InsertIndex <= &Options.Count AND &Options.Item(&InsertIndex) = &Option &count.FromString(&OptionIndexes.Item(&InsertIndex)) &count += 1 &OptionIndexes.Remove(&InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) Else &Options.Add(&Option, &InsertIndex) &OptionIndexes.Add(!'1', &InsertIndex) EndIf EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
